8	import org.springframework.web.bind.MissingRequestHeaderException;
9	import org.springframework.web.bind.annotation.ExceptionHandler;
10	import org.springframework.web.bind.annotation.RestControllerAdvice;
11	import org.springframework.web.servlet.resource.NoResourceFoundException;
12	
13	/**
14	 * 全局异常映射：业务异常按 ApiException 状态返回；参数解析/校验失败统一 400。
15	 */
16	@RestControllerAdvice
17	public class GlobalExceptionHandler {
18	
19	    @ExceptionHandler(ApiException.class)
20	    public ResponseEntity<ErrorResponse> handleApi(ApiException ex) {
21	        return ResponseEntity.status(ex.status())
22	                .body(new ErrorResponse(ex.code(), ex.getMessage()));
23	    }
24	
25	    @ExceptionHandler(MethodArgumentNotValidException.class)
26	    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
27	        String message = ex.getBindingResult().getFieldErrors().stream()
28	                .findFirst()
29	                .map(FieldError::getDefaultMessage)
30	                .orElse("请求参数不合法");
31	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
32	                .body(new ErrorResponse("INVALID_ARGUMENT", message));
33	    }
34	
35	    @ExceptionHandler(HttpMessageNotReadableException.class)
36	    public ResponseEntity<ErrorResponse> handleNotReadable(HttpMessageNotReadableException ex) {
37	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
38	                .body(new ErrorResponse("INVALID_ARGUMENT", "请求体无法解析: " + ex.getMostSpecificCause().getMessage()));
39	    }
40	
41	    @ExceptionHandler(MissingRequestHeaderException.class)
42	    public ResponseEntity<ErrorResponse> handleMissingHeader(MissingRequestHeaderException ex) {
43	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
44	                .body(new ErrorResponse("INVALID_ARGUMENT", "缺少必需请求头: " + ex.getHeaderName()));
45	    }
46	
47	    @ExceptionHandler(NoResourceFoundException.class)
48	    public ResponseEntity<ErrorResponse> handleNoResource(NoResourceFoundException ex) {
49	        return ResponseEntity.status(HttpStatus.NOT_FOUND)
50	                .body(new ErrorResponse("NOT_FOUND", "资源不存在"));
51	    }
52	}
