    weigh(batch, "A", "5", 5L, 409);
    // 期望版本匹配（当前版本 1）→ 201
    weigh(batch, "A", "5", 1L, 201);
    // 更正也校验期望版本（当前版本 2）
    correct(batch, w1, "12", 99L, 409);
    correct(batch, w1, "12", 2L, 201);
    JsonNode chain = chain(batch);
    assertEquals(3, chain.path("version").asLong());
